package com.argument.correctiontrial;
import com.argument.adjudication.*;
import com.argument.finalreview.*;
import com.argument.version.*;
import com.argument.version.port.*;
import com.argument.version.port.VersionIdentity.Actor;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.util.*;
import org.springframework.context.annotation.Profile;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import static com.argument.adjudication.AdjudicationService.*;

@Service @Profile("(local | test) & !prod")
public class CorrectionTrialService {
 private final JdbcTemplate jdbc;private final ObjectMapper mapper;private final VersionRepository versions;private final AnnotationDependencies data;private final FinalReviewService finals;private final FinalReviewRepository finalStore;private final AdjudicationService adjudication;private final AdjudicationRepository sessions;private final AdjudicationDependencies deps;
 public CorrectionTrialService(JdbcTemplate jdbc,ObjectMapper mapper,VersionRepository versions,AnnotationDependencies data,FinalReviewService finals,FinalReviewRepository finalStore,AdjudicationService adjudication,AdjudicationRepository sessions,AdjudicationDependencies deps){this.jdbc=jdbc;this.mapper=mapper;this.versions=versions;this.data=data;this.finals=finals;this.finalStore=finalStore;this.adjudication=adjudication;this.sessions=sessions;this.deps=deps;}
 @Transactional public ObjectNode create(Actor actor,String id,String key,int expected,ObjectNode body){VersionJson.uuid(key);var initial=finals.read(actor,id);String c=initial.path("version").path("taskDocumentId").asText();versions.lockCase(c);var doc=data.lock("taskDocument",c);var task=data.lock("task",doc.path("taskId").asText());var parent=finals.read(actor,id);var v=(ObjectNode)parent.path("version");var old=sessions.session(v.path("sessionId").asText(),true);adjudication.read(actor,old.path("id").asText());String op="TRIAL-CORRECTION:"+id,hash=VersionJson.canonicalHash(body);var cached=versions.receipt(actor.id(),op,key,hash);if(cached!=null)return cached;require(expected==v.path("recordVersion").asInt(),com.argument.common.exception.ErrorCode.VERSION_CONFLICT,"最终版本已变化，请刷新");require("IN_PROGRESS".equals(task.path("status").asText())&&"ADJUDICATING".equals(doc.path("status").asText()),com.argument.common.exception.ErrorCode.LOCKED_RESOURCE,"任务或案例已锁定");var all=finalStore.versions(c);require(all.get(all.size()-1).path("id").equals(v.get("id"))&&"DRAFT".equals(v.path("status").asText())&&finalStore.history(id).stream().anyMatch(h->"FV04".equals(h.path("operation").asText())),com.argument.common.exception.ErrorCode.INVALID_FINAL_STATE,"仅最新且经审查退回的最终草稿可创建补正轮次");String reason=body.path("reason").asText();require(!reason.isBlank()&&reason.length()<=2000,com.argument.common.exception.ErrorCode.VALIDATION_ERROR,"补正理由需为 1–2000 字");require(jdbc.queryForObject("SELECT COUNT(*) FROM trial_correction_rounds WHERE parent_final_version_id=?",Integer.class,id)==0,com.argument.common.exception.ErrorCode.CONFLICT,"该最终版已有补正轮次，请进入原轮次");deps.checkExperts(old);
 var s=mapper.createObjectNode();String now=VersionJson.now();VersionJson.stamp(s,actor.id(),now);for(String f:List.of("taskDocumentId","arbiterAssignmentId","sourceVersionIds"))s.set(f,old.path(f).deepCopy());s.put("status","PROPOSITION_REVIEW").put("currentPhase","PROPOSITION_REVIEW").putNull("propositionCompletedAt").putNull("relationCompletedAt");s.put("correctionOriginVersionId",id).put("previousSessionId",old.path("id").asText()).put("correctionOriginDecisionSubject",decisionSubject(adjudication.current(combined(old),sessions.decisions(old.path("id").asText()))));sessions.insertSession(s);
 for(var item:deps.comparePropositions(adjudication.snapshots(old))){VersionJson.stamp(item,actor.id(),now);item.put("sessionId",s.path("id").asText()).put("status","OPEN").putNull("decisionId");sessions.insertItem(item,"PROPOSITION");}
 var round=mapper.createObjectNode();VersionJson.stamp(round,actor.id(),now);round.put("parentFinalVersionId",id).put("previousSessionId",old.path("id").asText()).put("sessionId",s.path("id").asText()).put("reason",reason).put("expertInheritance","NONE_RECHECK_REQUIRED").put("teamReviewRequired",true);round.set("sourceVersionIds",s.path("sourceVersionIds").deepCopy());jdbc.update("INSERT INTO trial_correction_rounds(id,parent_final_version_id,session_id,payload_json) VALUES(?,?,?,?)",round.path("id").asText(),id,s.path("id").asText(),round.toString());var oldBefore=old.deepCopy();old.put("correctionSessionId",s.path("id").asText());touch(old,actor);sessions.saveSession(old);sessions.transition("TRIAL_CORRECTION_SUPERSEDE",actor.id(),body,oldBefore,old);v.put("correctionSessionId",s.path("id").asText());touch(v,actor);finalStore.saveVersion(v);finalStore.transition("TRIAL_CORRECTION_OPEN",actor.id(),body,initial.path("version").deepCopy(),v);sessions.transition("TRIAL_CORRECTION_CREATE",actor.id(),body,old,s);versions.receipt(actor.id(),op,key,hash,round,mapper.createObjectNode(),round,reason);return round;
 }
 private List<ObjectNode> combined(ObjectNode s){var items=new ArrayList<>(sessions.items(s.path("id").asText(),"PROPOSITION"));items.addAll(sessions.items(s.path("id").asText(),"RELATION"));return items;}
 public ObjectNode read(Actor actor,String id){finals.read(actor,id);var records=jdbc.queryForList("SELECT payload_json FROM trial_correction_rounds WHERE parent_final_version_id=?",String.class,id);var result=mapper.createObjectNode();var items=result.putArray("items");records.forEach(r->items.add(VersionJson.parse(mapper,r)));return result;}
}
